"use client";

import { motion } from "motion/react";
import * as React from "react";

import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { AdvancedSelectDropdown } from "@/registry/new-york/advanced-select/AdvancedSelectDropdown";
import { useAdvancedSelectState } from "@/registry/new-york/advanced-select/AdvancedSelectState";
import {
  AdvancedSelectTriggerContent,
  AdvancedSelectTriggerIcon,
} from "@/registry/new-york/advanced-select/AdvancedSelectTrigger";
import type * as AdvancedSelectTypesModule from "@/registry/new-york/advanced-select/AdvancedSelectTypes";
import { contentAnimationVariants } from "@/registry/new-york/advanced-select/AdvancedSelectVariants";

export type AdvancedSelectOption =
  AdvancedSelectTypesModule.AdvancedSelectOption;
export type AdvancedSelectProps = AdvancedSelectTypesModule.AdvancedSelectProps;
const EMPTY_SELECTION: string[] = [];

const AdvancedSelectRender: React.ForwardRefRenderFunction<
  HTMLButtonElement,
  AdvancedSelectProps
> = (
  {
    options,
    onValueChange,
    value: controlledValue,
    variant,
    defaultValue = EMPTY_SELECTION,
    searchable = false,
    placeholder = "Select options",
    maxCount = 3,
    modalPopover = false,
    asChild: _asChild = false,
    className,
    leftIcon: LeftIcon,
    rightIcon: RightIcon,
    loading = false,
    onCreate,
    ...props
  },
  ref
) => {
  const state = useAdvancedSelectState({
    controlledValue,
    defaultValue,
    maxCount,
    onCreate,
    onValueChange,
    options,
    searchable,
  });
  return (
    <Popover
      open={state.isPopoverOpen}
      onOpenChange={(value) => state.setIsPopoverOpen(value)}
      modal={modalPopover}
    >
      <PopoverTrigger
        render={
          <Button
            ref={ref}
            {...props}
            onClick={state.handleTogglePopover}
            disabled={loading || props.disabled}
            className={cn(
              "flex h-auto min-h-10 w-full items-center justify-between rounded-md border bg-inherit p-1 transition-all duration-200 hover:bg-inherit [&_svg]:pointer-events-auto",
              loading && "cursor-not-allowed opacity-50",
              className
            )}
            data-slot="advanced-select-trigger"
          />
        }
      >
        <div className="flex w-full items-center justify-between">
          <div className="flex min-h-[28px] flex-1 items-center pl-2">
            <AdvancedSelectTriggerContent
              LeftIcon={LeftIcon}
              loading={loading}
              maxCount={maxCount}
              onClearExtra={() => state.clearExtraOptions()}
              onMiddleClick={state.handleMiddleClick}
              onRemove={(value) => state.toggleOption(value)}
              optionsByValue={state.optionsByValue}
              placeholder={placeholder}
              selectedValues={state.selectedValues}
              variant={variant}
            />
          </div>
          <div className="ml-2 flex shrink-0 items-center justify-center pr-2">
            <AdvancedSelectTriggerIcon RightIcon={RightIcon} />
          </div>
        </div>
      </PopoverTrigger>

      <PopoverContent
        className="w-auto p-0"
        align="start"
        data-slot="advanced-select-content"
        render={
          <motion.div
            initial="hidden"
            animate="visible"
            variants={contentAnimationVariants}
            className="w-[var(--anchor-width)]"
            style={{
              maxWidth: "calc(100vw - 32px)",
              width: "var(--anchor-width)",
            }}
          />
        }
      >
        <AdvancedSelectDropdown
          {...{
            handleClearClick: state.handleClearClick,
            handleCloseClick: state.handleCloseClick,
            handleCreateOption: state.handleCreateOption,
            handleInputKeyDown: state.handleInputKeyDown,
            handleOptionClick: state.handleOptionClick,
            handleSearchChange: state.handleSearchChange,
            handleSelectAllClick: state.handleSelectAllClick,
          }}
          {...{
            handleClearClick: state.handleClearClick,
            handleCloseClick: state.handleCloseClick,
            handleCreateOption: state.handleCreateOption,
            handleInputKeyDown: state.handleInputKeyDown,
            handleOptionClick: state.handleOptionClick,
            handleSearchChange: state.handleSearchChange,
            handleSelectAllClick: state.handleSelectAllClick,
          }}
          filteredOptions={state.filteredOptions}
          optionsLength={options.length}
          searchable={searchable}
          searchQuery={state.searchQuery}
          selectedValues={state.selectedValues}
          toggleOption={state.toggleOption}
        />
      </PopoverContent>
    </Popover>
  );
};
export const AdvancedSelect = React.forwardRef<
  HTMLButtonElement,
  AdvancedSelectProps
>(AdvancedSelectRender);
AdvancedSelect.displayName = "AdvancedSelect";

"use client";

import * as React from "react";

import { Command, CommandInput, CommandList } from "@/components/ui/command";
import {
  AdvancedSelectEmptyState,
  AdvancedSelectFooter,
  AdvancedSelectOptionsGroup,
} from "@/registry/new-york/advanced-select/AdvancedSelectDropdownParts";
import type { AdvancedSelectOption } from "@/registry/new-york/advanced-select/AdvancedSelectTypes";

export const AdvancedSelectDropdown = ({
  filteredOptions,
  handleClearClick,
  handleCloseClick,
  handleCreateOption,
  handleInputKeyDown,
  handleOptionClick,
  handleSearchChange,
  handleSelectAllClick,
  optionsLength,
  searchable,
  searchQuery,
  selectedValues,
  toggleOption,
}: {
  filteredOptions: AdvancedSelectOption[];
  handleClearClick: (event: React.MouseEvent) => void;
  handleCloseClick: (event: React.MouseEvent) => void;
  handleCreateOption: () => void;
  handleInputKeyDown: (event: React.KeyboardEvent<HTMLInputElement>) => void;
  handleOptionClick: (value: string, event: React.MouseEvent) => void;
  handleSearchChange: (value: string) => void;
  handleSelectAllClick: (event: React.MouseEvent) => void;
  optionsLength: number;
  searchable: boolean;
  searchQuery: string;
  selectedValues: string[];
  toggleOption: (value: string) => void;
}) => (
  <Command shouldFilter={false}>
    {searchable && (
      <CommandInput
        placeholder="Search..."
        onKeyDown={handleInputKeyDown}
        onValueChange={handleSearchChange}
        value={searchQuery}
        data-slot="advanced-select-search"
      />
    )}
    <CommandList className="max-h-[300px]">
      <AdvancedSelectEmptyState
        filteredOptions={filteredOptions}
        onCreate={handleCreateOption}
        searchable={searchable}
        searchQuery={searchQuery}
      />
      <AdvancedSelectOptionsGroup
        filteredOptions={filteredOptions}
        onCreate={handleCreateOption}
        onOptionClick={handleOptionClick}
        onSelectAll={handleSelectAllClick}
        onToggleOption={toggleOption}
        optionsLength={optionsLength}
        searchable={searchable}
        searchQuery={searchQuery}
        selectedValues={selectedValues}
      />
      <AdvancedSelectFooter
        hasSelection={selectedValues.length > 0}
        onClear={handleClearClick}
        onClose={handleCloseClick}
      />
    </CommandList>
  </Command>
);

"use client";

import { motion } from "motion/react";
import * as React from "react";

import {
  CommandEmpty,
  CommandGroup,
  CommandSeparator,
} from "@/components/ui/command";
import { Separator } from "@/components/ui/separator";
import {
  AdvancedSelectCreateSuggestion,
  AdvancedSelectOptionRow,
  AdvancedSelectSelectAllOption,
} from "@/registry/new-york/advanced-select/AdvancedSelectOptionRow";
import type { AdvancedSelectOption } from "@/registry/new-york/advanced-select/AdvancedSelectTypes";

export const AdvancedSelectEmptyState = ({
  filteredOptions,
  onCreate,
  searchable,
  searchQuery,
}: {
  filteredOptions: AdvancedSelectOption[];
  onCreate?: (() => void) | undefined;
  searchable: boolean;
  searchQuery: string;
}) => {
  if (searchable && filteredOptions.length === 0 && searchQuery && onCreate) {
    return (
      <CommandEmpty className="py-0">
        <button
          type="button"
          className="hover:bg-accent hover:text-accent-foreground flex cursor-pointer items-center px-2 py-1.5 text-sm"
          onClick={onCreate}
        >
          <div className="mr-2 flex h-4 w-4 items-center justify-center rounded-sm">
            <span className="text-xl">+</span>
          </div>
          Create &quot;{searchQuery}&quot;
        </button>
      </CommandEmpty>
    );
  }
  if (
    searchable &&
    filteredOptions.length === 0 &&
    (!searchQuery || !onCreate)
  ) {
    return (
      <CommandEmpty className="ml-2 py-1.5">No results found.</CommandEmpty>
    );
  }
  return null;
};
export const AdvancedSelectOptionsGroup = ({
  filteredOptions,
  onCreate,
  onOptionClick,
  onSelectAll,
  onToggleOption,
  optionsLength,
  searchable,
  searchQuery,
  selectedValues,
}: {
  filteredOptions: AdvancedSelectOption[];
  onCreate?: (() => void) | undefined;
  onOptionClick: (value: string, event: React.MouseEvent) => void;
  onSelectAll: (event: React.MouseEvent) => void;
  onToggleOption: (value: string) => void;
  optionsLength: number;
  searchable: boolean;
  searchQuery: string;
  selectedValues: string[];
}) => (
  <CommandGroup>
    {!searchable && (
      <>
        <AdvancedSelectSelectAllOption
          allSelected={selectedValues.length === optionsLength}
          onClick={onSelectAll}
        />
        <CommandSeparator />
      </>
    )}
    {filteredOptions.map((option, index) => (
      <AdvancedSelectOptionRow
        key={option.value}
        index={index}
        onClick={onOptionClick}
        onToggle={onToggleOption}
        option={option}
        selected={selectedValues.includes(option.value)}
      />
    ))}
    <AdvancedSelectCreateSuggestion
      filteredOptions={filteredOptions}
      onCreate={onCreate}
      searchable={searchable}
      searchQuery={searchQuery}
    />
  </CommandGroup>
);
export const AdvancedSelectFooter = ({
  hasSelection,
  onClear,
  onClose,
}: {
  hasSelection: boolean;
  onClear: (event: React.MouseEvent) => void;
  onClose: (event: React.MouseEvent) => void;
}) => (
  <CommandGroup>
    <div className="flex items-center justify-between">
      {hasSelection && (
        <>
          <motion.div
            whileHover={{
              scale: 1.05,
            }}
            whileTap={{
              scale: 0.95,
            }}
            className="hover:bg-accent hover:text-accent-foreground flex-1 cursor-pointer justify-center py-1.5 text-center text-sm"
            onClick={onClear}
          >
            Clear
          </motion.div>
          <Separator orientation="vertical" className="flex h-full min-h-6" />
        </>
      )}
      <motion.div
        whileHover={{
          scale: 1.05,
        }}
        whileTap={{
          scale: 0.95,
        }}
        className="hover:bg-accent hover:text-accent-foreground flex-1 cursor-pointer justify-center py-1.5 text-center text-sm"
        onClick={onClose}
      >
        Close
      </motion.div>
    </div>
  </CommandGroup>
);

"use client";

import { CheckIcon } from "lucide-react";
import { motion } from "motion/react";
import * as React from "react";

import { cn } from "@/lib/utils";
import type { AdvancedSelectOption } from "@/registry/new-york/advanced-select/AdvancedSelectTypes";
import { optionMatchesSearch } from "@/registry/new-york/advanced-select/AdvancedSelectUtils";
import { optionAnimationVariants } from "@/registry/new-york/advanced-select/AdvancedSelectVariants";

const AdvancedSelectCheckbox = ({ checked }: { checked: boolean }) => (
  <div
    className={cn(
      "border-primary mr-2 flex h-4 w-4 items-center justify-center rounded-sm border",
      checked
        ? "bg-primary text-primary-foreground"
        : "opacity-50 [&_svg]:invisible"
    )}
  >
    <CheckIcon className="h-4 w-4" />
  </div>
);
export const AdvancedSelectSelectAllOption = ({
  allSelected,
  onClick,
}: {
  allSelected: boolean;
  onClick: (event: React.MouseEvent) => void;
}) => (
  <motion.div
    variants={optionAnimationVariants}
    initial="hidden"
    animate="visible"
    custom={0}
    className="hover:bg-accent hover:text-accent-foreground relative flex cursor-pointer items-center rounded-sm px-2 py-1.5 text-sm select-none"
    onClick={onClick}
    data-select-all="true"
  >
    <AdvancedSelectCheckbox checked={allSelected} />
    <span>(Select All)</span>
  </motion.div>
);
export const AdvancedSelectOptionRow = ({
  index,
  onClick,
  onToggle,
  option,
  selected,
}: {
  index: number;
  onClick: (value: string, event: React.MouseEvent) => void;
  onToggle: (value: string) => void;
  option: AdvancedSelectOption;
  selected: boolean;
}) => {
  const IconComponent = option.icon;
  return (
    <motion.div
      variants={optionAnimationVariants}
      initial="hidden"
      animate="visible"
      custom={index + 1}
      className={cn(
        "relative flex cursor-pointer items-center rounded-sm px-2 py-1.5 text-sm transition-colors select-none",
        selected
          ? "bg-accent text-accent-foreground"
          : "hover:bg-accent hover:text-accent-foreground"
      )}
      onClick={(event) => onClick(option.value, event)}
      onMouseDown={(event) => {
        if (event.button === 1) {
          event.preventDefault();
          onToggle(option.value);
        }
      }}
    >
      <AdvancedSelectCheckbox checked={selected} />
      {IconComponent && (
        <IconComponent className="text-muted-foreground mr-2 h-4 w-4" />
      )}
      {option.emoji && <span className="mr-2">{option.emoji}</span>}
      <span>{option.label || option.value}</span>
    </motion.div>
  );
};
export const AdvancedSelectCreateSuggestion = ({
  filteredOptions,
  onCreate,
  searchQuery,
  searchable,
}: {
  filteredOptions: AdvancedSelectOption[];
  onCreate?: (() => void) | undefined;
  searchable: boolean;
  searchQuery: string;
}) => {
  const normalizedQuery = searchQuery.toLowerCase();
  const hasExactMatch = filteredOptions.some((option) =>
    optionMatchesSearch(option, normalizedQuery)
  );
  const showCreateSuggestion =
    searchable &&
    Boolean(onCreate) &&
    Boolean(searchQuery) &&
    filteredOptions.length > 0 &&
    !hasExactMatch;
  if (!(showCreateSuggestion && onCreate)) {
    return null;
  }
  return (
    <motion.div
      variants={optionAnimationVariants}
      initial="hidden"
      animate="visible"
      custom={filteredOptions.length + 1}
      className="hover:bg-accent hover:text-accent-foreground relative flex cursor-pointer items-center rounded-sm px-2 py-1.5 text-sm transition-colors select-none"
      onClick={onCreate}
    >
      <div className="mr-2 flex h-4 w-4 items-center justify-center rounded-sm">
        <span className="text-xl">+</span>
      </div>
      <span>Create &quot;{searchQuery}&quot;</span>
    </motion.div>
  );
};

"use client";

import * as React from "react";

import type { AdvancedSelectOption } from "@/registry/new-york/advanced-select/AdvancedSelectTypes";
import { getFilteredOptions } from "@/registry/new-york/advanced-select/AdvancedSelectUtils";

export const useAdvancedSelectState = ({
  controlledValue,
  defaultValue,
  maxCount,
  onCreate,
  onValueChange,
  options,
  searchable,
}: {
  controlledValue?: string[] | undefined;
  defaultValue: string[];
  maxCount: number;
  onCreate?: ((value: string) => void) | undefined;
  onValueChange?: ((value: string[]) => void) | undefined;
  options: AdvancedSelectOption[];
  searchable: boolean;
}) => {
  const [internalSelectedValues, setInternalSelectedValues] = React.useState<
    string[]
  >(controlledValue || defaultValue);
  const selectedValues = controlledValue ?? internalSelectedValues;

  const [isPopoverOpen, setIsPopoverOpen] = React.useState(false);
  const [searchQuery, setSearchQuery] = React.useState("");

  const updateValues = (newValues: string[]) => {
    if (controlledValue === undefined) {
      setInternalSelectedValues(newValues);
    }
    onValueChange?.(newValues);
  };

  const toggleOption = (option: string) => {
    const newSelectedValues = selectedValues.includes(option)
      ? selectedValues.filter((value) => value !== option)
      : [...selectedValues, option];
    updateValues(newSelectedValues);
  };

  const handleClear = () => updateValues([]);
  const handleTogglePopover = () => setIsPopoverOpen((previous) => !previous);
  const clearExtraOptions = () =>
    updateValues(selectedValues.slice(0, maxCount));
  const toggleAll = () => {
    if (selectedValues.length === options.length) {
      handleClear();
    } else {
      updateValues(options.map((option) => option.value));
    }
  };

  const handleInputKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      setIsPopoverOpen(true);
    } else if (event.key === "Backspace" && !event.currentTarget.value) {
      const newSelectedValues = [...selectedValues];
      newSelectedValues.pop();
      updateValues(newSelectedValues);
    }
  };

  const handleOptionClick = (optionValue: string, event: React.MouseEvent) => {
    event.preventDefault();
    event.stopPropagation();
    toggleOption(optionValue);
  };
  const handleSelectAllClick = (event: React.MouseEvent) => {
    event.preventDefault();
    event.stopPropagation();
    toggleAll();
  };
  const handleClearClick = (event: React.MouseEvent) => {
    event.preventDefault();
    event.stopPropagation();
    handleClear();
  };
  const handleCloseClick = (event: React.MouseEvent) => {
    event.preventDefault();
    event.stopPropagation();
    setIsPopoverOpen(false);
  };
  const handleMiddleClick = (
    value: string,
    event: React.MouseEvent<HTMLDivElement>
  ) => {
    if (event.button === 1) {
      event.preventDefault();
      toggleOption(value);
    }
  };
  const handleCreateOption = () => {
    if (onCreate && searchQuery.trim()) {
      onCreate(searchQuery.trim());
      setSearchQuery("");
    }
  };
  const optionsByValue = React.useMemo(
    () => new Map(options.map((option) => [option.value, option])),
    [options]
  );

  return {
    clearExtraOptions,
    filteredOptions: getFilteredOptions(options, searchable, searchQuery),
    handleClearClick,
    handleCloseClick,
    handleCreateOption,
    handleInputKeyDown,
    handleMiddleClick,
    handleOptionClick,
    handleSearchChange: setSearchQuery,
    handleSelectAllClick,
    handleTogglePopover,
    isPopoverOpen,
    optionsByValue,
    searchQuery,
    selectedValues,
    setIsPopoverOpen,
    toggleOption,
  };
};

"use client";

import { ChevronDown, XIcon } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import * as React from "react";

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import type {
  AdvancedSelectOption,
  AdvancedSelectVariant,
} from "@/registry/new-york/advanced-select/AdvancedSelectTypes";
import {
  advancedSelectVariants,
  badgeAnimationVariants,
} from "@/registry/new-york/advanced-select/AdvancedSelectVariants";

const AdvancedSelectBadgeItem = ({
  onMiddleClick,
  onRemove,
  option,
  value,
  variant,
}: {
  onMiddleClick: (
    value: string,
    event: React.MouseEvent<HTMLDivElement>
  ) => void;
  onRemove: (value: string) => void;
  option?: AdvancedSelectOption | undefined;
  value: string;
  variant: AdvancedSelectVariant;
}) => {
  const IconComponent = option?.icon;

  return (
    <motion.div
      variants={badgeAnimationVariants}
      initial="initial"
      animate="animate"
      exit="exit"
      layout
      onMouseDown={(event) => onMiddleClick(value, event)}
    >
      <Badge
        className={cn(advancedSelectVariants({ variant }))}
        data-slot="advanced-select-badge"
      >
        {IconComponent && <IconComponent className="mr-2 h-4 w-4" />}
        {option?.emoji && <span className="mr-2">{option.emoji}</span>}
        {option?.label || option?.value || value}
        <XIcon
          className="ml-2 h-3 w-3 cursor-pointer opacity-70 hover:opacity-100"
          onClick={(event) => {
            event.stopPropagation();
            onRemove(value);
          }}
        />
      </Badge>
    </motion.div>
  );
};

const AdvancedSelectBadgeList = ({
  maxCount,
  onClearExtra,
  onMiddleClick,
  onRemove,
  optionsByValue,
  selectedValues,
  variant,
}: {
  maxCount: number;
  onClearExtra: () => void;
  onMiddleClick: (
    value: string,
    event: React.MouseEvent<HTMLDivElement>
  ) => void;
  onRemove: (value: string) => void;
  optionsByValue: Map<string, AdvancedSelectOption>;
  selectedValues: string[];
  variant: AdvancedSelectVariant;
}) => (
  <div className="flex w-full flex-wrap items-center gap-1">
    <AnimatePresence>
      {selectedValues.slice(0, maxCount).map((value) => (
        <AdvancedSelectBadgeItem
          key={value}
          onMiddleClick={onMiddleClick}
          onRemove={onRemove}
          option={optionsByValue.get(value)}
          value={value}
          variant={variant}
        />
      ))}
    </AnimatePresence>
    {selectedValues.length > maxCount && (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.3 }}
      >
        <Badge variant="outline" className="ml-1" onClick={onClearExtra}>
          +{selectedValues.length - maxCount} more
        </Badge>
      </motion.div>
    )}
  </div>
);

export const AdvancedSelectTriggerContent = ({
  LeftIcon,
  loading,
  maxCount,
  onClearExtra,
  onMiddleClick,
  onRemove,
  optionsByValue,
  placeholder,
  selectedValues,
  variant,
}: {
  LeftIcon?: React.ElementType | undefined;
  loading: boolean;
  maxCount: number;
  onClearExtra: () => void;
  onMiddleClick: (
    value: string,
    event: React.MouseEvent<HTMLDivElement>
  ) => void;
  onRemove: (value: string) => void;
  optionsByValue: Map<string, AdvancedSelectOption>;
  placeholder: string;
  selectedValues: string[];
  variant: AdvancedSelectVariant;
}) => {
  if (loading) {
    return (
      <div className="flex items-center">
        <div className="border-primary mr-2 h-4 w-4 animate-spin rounded-full border-2 border-t-transparent" />
        <span className="text-muted-foreground">Loading...</span>
      </div>
    );
  }

  return (
    <>
      {LeftIcon && (
        <LeftIcon className="text-muted-foreground mr-2 h-4 w-4 shrink-0" />
      )}
      {selectedValues.length > 0 ? (
        <AdvancedSelectBadgeList
          maxCount={maxCount}
          onClearExtra={onClearExtra}
          onMiddleClick={onMiddleClick}
          onRemove={onRemove}
          optionsByValue={optionsByValue}
          selectedValues={selectedValues}
          variant={variant}
        />
      ) : (
        <div className="text-muted-foreground truncate px-2">{placeholder}</div>
      )}
    </>
  );
};

export const AdvancedSelectTriggerIcon = ({
  RightIcon,
}: {
  RightIcon?: React.ElementType | undefined;
}) =>
  RightIcon ? (
    <RightIcon className="text-foreground h-5 w-5" />
  ) : (
    <ChevronDown className="h-4 w-4 opacity-50" />
  );

import type { VariantProps } from "class-variance-authority";
import * as React from "react";

import type { SelectOption } from "@/lib/types";
import type { advancedSelectVariants } from "@/registry/new-york/advanced-select/AdvancedSelectVariants";

export type AdvancedSelectOption = SelectOption;

export interface AdvancedSelectProps
  extends
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof advancedSelectVariants> {
  options: AdvancedSelectOption[];
  onValueChange?: ((value: string[]) => void) | undefined;
  value?: string[] | undefined;
  defaultValue?: string[] | undefined;
  searchable?: boolean | undefined;
  placeholder?: string | undefined;
  maxCount?: number | undefined;
  modalPopover?: boolean | undefined;
  asChild?: boolean | undefined;
  className?: string | undefined;
  leftIcon?: React.ElementType | undefined;
  rightIcon?: React.ElementType | undefined;
  loading?: boolean | undefined;
  onCreate?: ((value: string) => void) | undefined;
}

export type AdvancedSelectVariant = AdvancedSelectProps["variant"];

import type { AdvancedSelectOption } from "@/registry/new-york/advanced-select/AdvancedSelectTypes";

export const getFilteredOptions = (
  options: AdvancedSelectOption[],
  searchable: boolean,
  searchQuery: string
) => {
  if (!(searchable && searchQuery)) {
    return options;
  }

  return options.filter((option) =>
    (option.label || option.value)
      .toLowerCase()
      .includes(searchQuery.toLowerCase())
  );
};

export const optionMatchesSearch = (
  option: AdvancedSelectOption,
  normalizedQuery: string
) =>
  option.label?.toLowerCase() === normalizedQuery ||
  option.value.toLowerCase() === normalizedQuery;

import { cva } from "class-variance-authority";

export const advancedSelectVariants = cva("m-1", {
  defaultVariants: {
    variant: "default",
  },
  variants: {
    variant: {
      default: "border-foreground/10 text-foreground bg-card hover:bg-card/80",
      destructive:
